import numpy as np
lam=1.5406
a,b,c_,al,be,ga=2.91659,4.9786,5.21562,90.0334,104.4135,90.0063
al,be,ga=np.radians([al,be,ga])
V=a*b*c_*np.sqrt(1-np.cos(al)**2-np.cos(be)**2-np.cos(ga)**2+2*np.cos(al)*np.cos(be)*np.cos(ga))
A=np.array([[a,0,0],[b*np.cos(ga),b*np.sin(ga),0],[c_*np.cos(be),c_*(np.cos(al)-np.cos(be)*np.cos(ga))/np.sin(ga),V/(a*b*np.sin(ga))]])
B=np.linalg.inv(A).T
res=[]
for h in range(-4,5):
  for k in range(-4,5):
    for l in range(-4,5):
      if (h,k,l)==(0,0,0): continue
      g=np.array([h,k,l])@B
      d=1/np.linalg.norm(g)
      if lam/(2*d)>=1:
        tt=2*np.degrees(np.arcsin(lam/(2*d)))
        if 10<=tt<=70: res.append((round(tt,2),(h,k,l)))
res.sort()
for r in res: print(r)
print('Fm-3m:')
a0=6.6266
for h,k,l in [(1,1,1),(2,0,0),(2,2,0),(3,1,1),(2,2,2),(4,0,0),(3,3,1),(4,2,0),(4,2,2)]:
  d=a0/np.sqrt(h*h+k*k+l*l); print((h,k,l), round(2*np.degrees(np.arcsin(lam/(2*d))),2))

